window.substringMatcher = function (strs) {
    return function findMatches(q, cb) {
        var matches, substringRegex;
        matches = [];
        substrRegex = new RegExp(q, 'i');
        $.each(strs, function (i, str) {
            if (substrRegex.test(str)) {
                matches.push(str);
            }
        });

        cb(matches);
    };
};


function autocomplete(itm) {
    $(itm).typeahead(t_settings, {
        name: 'Key-' + idx,
        limit: 10,
        source: substringMatcher(hints)
    });
}



var t_settings = {
    hint: false,
    highlight: true,
    classNames: {
        menu: "dropdown-menu suggestion-list",
        suggestion: "suggestion-item"
    }
}


$(document).ready(function () {
    //-----------------------------------------------------------------
    //--- LoadHints ------------------------------------------
    //-----------------------------------------------------------------

    $.getJSON("/admin/Products/LoadHints", function (response) {
        hints = response.data;
        autocomplete('.typeahead');
    })

    
    //-----------------------------------------------------------------
    //--- Shipping  ------------------------------------------
    //-----------------------------------------------------------------
    $('#Shipping').on('change', function () {

        if ($(this).is(":checked")) {
            $('#IsFreeShipping').prop('disabled', false);
            $('.shipping_inputs input').each((indx, itm) => $(itm).prop('disabled', false));
        } else {
            $('#IsFreeShipping').prop('disabled', true).prop('checked', false);
            $('.shipping_inputs input').each((indx, itm) => $(itm).prop('disabled', true).val(0));
        }

    })
    //-----------------------------------------------------------------
    //--- select picker  ------------------------------------------
    //-----------------------------------------------------------------

   
 

$('#publish_product').on('change',function(e){
    var $this = $(this);
    

    $.get('/Admin/Products/Publish/'+ pid)
    .done(function (res){
        if(res.success){
            if($this.is(":checked")){
                $notification.success("", "Published successfully", 2000, "fa fa-check");
            }else{
                $notification.warning("", "Unpublished successfully", 2000, "fa fa-check");
            }
        }
    })
    .fail(function (jqXHR, Status) {
        $notification.error("Error!", jqXHR.statusText, 2000, "fa fa-exclamation-circle");
    })
});



    $(document).on('click','.delete-product' ,function(e){
        e.preventDefault();
        var $this = $(this);
        
        swal({
            title: 'Are you sure?',
            text: "You won't be able to revert this!",
            type: 'error',
            showCancelButton: true,
            confirmButtonColor: '#3085d6',
            cancelButtonColor: '#df4818',
            confirmButtonText: 'Yes, delete it!'
        }).then((result) => {
            if (result.value) {
                 
                
                $.ajax({
                    url: '/Admin/Products/delete/'+ pid ,
                    type: 'Get',
                    dataType: "json",  
                    data: {
                        redirection : true
                    }
                })
                .done(function(data){
                    if(data.success){
                        $notification.success("", "Published successfully", 2000, "fa fa-check");
                        window.location.assign(window.location.origin + '/Admin/products');
                    }else{
                        $notification.error("Error!", "", 2000, "fa fa-exclamation-circle");
                    }
                   
                       
                 }
            ) .fail(function (jqXHR, Status) {
                $notification.error("Error!", jqXHR.statusText, 2000, "fa fa-exclamation-circle");
            })
               
            }
        })
    })

}) // end document ready fn
$(document).ready(function () {
    
    //-----------------------------------------------------------------
    //--- specifications  ------------------------------------------
    //-----------------------------------------------------------------

    var specifications_template = '<div class="form-group clearfix inputitem" id="sitem-##">' +
    '<div class="col-md-3 col-sm-3 col-xs-12 scrollable-dropdown-menu">' +
    '<input type="text" id="Key-##" name="Specifications[##].Key" class="form-control typeahead" value="" required/>' +
    '</div>' +
    '<div class="col-md-8 col-sm-7 col-xs-12">' +
    '<textarea type="text" id="Value-##" name="Specifications[##].Value" class="form-control"  rows="1"></textarea>' +
    '</div>' +
    '<div class="col-md-1 col-sm-2 col-xs-12">' +
    '<a class="btn btn-remove-content m-t0 remove-content"  data-id="##">' +
    '<i class="fa fa-trash-o"></i>' +
    '</a></div></div>';

    $('#addItems').on('click', function (e) {
        e.preventDefault();
        var temp = specifications_template.replace(/##/g, idx);
        $('#s_wrapper').append(temp);
        autocomplete('#Key-' + idx)
        idx++;
    });

    $(document).on('click', '.remove-content', function (e) {
        e.preventDefault();
        if (idx > 0) {
            var id = $(this).data('id');

            $('#sitem-' + id).remove();
                $('.remove-content').addClass('disabled'); 
                var items = $('#s_wrapper').find('.inputitem');
                items.each(function (i, itm) {
                    var item = $(itm);
                    input = item.find('input[id^="Key-"]'),
                    textarea = item.find('textarea[id^="Value-"]');
                    item.attr('id', 'sitem-' + i);
                    input.attr("id", "Key-" + i).attr('name', "Specifications[" + i + "].Key");
                    textarea.attr("id", "Value-" + i).attr('name', "Specifications[" + i + "].Value");
                    item.find('.remove-content').attr('data-id', i);
                }); 
                $('.remove-content').removeClass('disabled');  
                idx--;
        }
    });
//-- end -- 
});
